					if (((y[l][0] <= i && y[l][3]>i) && (y[l][1] <= j && y[l][4]>j)) && (y[l][2] <= k && y[l][5]>k)) {

						p++;

					}

				}

				if (p >= m) {

					sum += a[i][j][k];

					b[i][j][k] = true;

				}

			}

		}

	}



	cout << sum << endl;



	return 0;

}
